// Opt-in "realistic" catalog overlay for UI / screenshot work (MOCK_REALISTIC=1 or
// createMockServer({ realistic: true })). It adds artists, albums and tracks shaped like
// what a real self-hosted library ends up with after YouTube / Spotify imports: very long
// titles with "(Official Video)" / "| Album" suffixes, "ft." credits, long multi-artist
// lists and one unbreakable word, plus a long-named playlist with 20 tracks. These are
// metadata strings only; audio, lyrics and artwork are still generated by the mock.
//
// It is OFF by default so the deterministic demo catalog (and the tests that count it)
// stays unchanged.

import { fold, randInt, rngFor, slugify } from './util.mjs'

const ARTISTS = [
  'Bad Bunny',
  'Duki',
  'Lucho SSJ',
  'Bizarrap',
  'Quevedo',
  'Nicki Nicole',
  'Tiago PZK',
  'Emilia',
  'María Becerra',
  'Paulo Londra',
  'Rusherking',
  'Khea',
  'De La Ghetto',
  'Chencho Corleone',
  'Bomba Estéreo',
  'Orquesta Sinfónica Nacional de la Radiotelevisión Española y Coro Juvenil de Madrid'
]

// [title, artist names..., ] grouped per album.
const ALBUMS = [
  {
    title: 'Un Verano Sin Ti',
    artist: 'Bad Bunny',
    year: 2022,
    type: 'album',
    tracks: [
      ['Bad Bunny - Un Verano Sin Ti (360° Visualizer) | Un Verano Sin Ti', ['Bad Bunny']],
      ['Me Porto Bonito', ['Bad Bunny', 'Chencho Corleone']],
      ['Tití Me Preguntó', ['Bad Bunny']],
      ['Ojitos Lindos', ['Bad Bunny', 'Bomba Estéreo']],
      ['Moscow Mule', ['Bad Bunny']]
    ]
  },
  {
    title: 'Antes de Ameri',
    artist: 'Duki',
    year: 2024,
    type: 'album',
    tracks: [
      ['Givenchy', ['Duki']],
      ['Rockstar', ['Duki']],
      ['She Don’t Give a FO', ['Duki', 'Khea']],
      ['Si Quieren Frontear ft. De La Ghetto & Quevedo (Remix Oficial Extendido)', ['Duki', 'De La Ghetto', 'Quevedo']],
      ['Antes de Perderte (Versión Acústica en Vivo desde el Estadio River Plate, Buenos Aires 2022)', ['Duki']],
      [
        'Party en el Barrio (feat. Paulo Londra, Nicki Nicole, Tiago PZK, Emilia, María Becerra y Rusherking)',
        ['Duki', 'Paulo Londra', 'Nicki Nicole', 'Tiago PZK', 'Emilia', 'María Becerra', 'Rusherking']
      ],
      ['Goteo', ['Duki']]
    ]
  },
  {
    title: 'Nadie Te Va a Querer Como Yo Te Quiero: Edición Deluxe Extendida con Remixes y Sesiones Acústicas en Vivo',
    artist: 'Lucho SSJ',
    year: 2025,
    type: 'album',
    tracks: [
      ['Lucho SSJ - Lucho SSJ ft. Duki - Perdoname Si Llego Tarde (Videoclip Oficial)', ['Lucho SSJ', 'Duki']],
      ['Supercalifragilisticoespialidosamenteinolvidablementeextraordinario', ['Lucho SSJ']],
      ['Te Busqué en Todas Partes', ['Lucho SSJ', 'Nicki Nicole']]
    ]
  },
  {
    title: 'BZRP Music Sessions, Vol. 1–60 (Colección Completa Remasterizada)',
    artist: 'Bizarrap',
    year: 2026,
    type: 'compilation',
    tracks: [
      ['DUKI x BIZARRAP || BZRP Music Sessions #50 (Official Video) [4K Remastered]', ['Bizarrap', 'Duki']],
      ['Quevedo: Bzrp Music Sessions, Vol. 52', ['Bizarrap', 'Quevedo']],
      ['Nicki Nicole: Bzrp Music Sessions, Vol. 13', ['Bizarrap', 'Nicki Nicole']]
    ]
  },
  {
    title: 'Sinfonía Nocturna para Orquesta, Coro y Sintetizadores Modulares (Grabación en Directo)',
    artist: 'Orquesta Sinfónica Nacional de la Radiotelevisión Española y Coro Juvenil de Madrid',
    year: 2023,
    type: 'album',
    tracks: [['Movimiento I: Allegro ma non troppo — Amanecer sobre la Ciudad Dormida', ['Orquesta Sinfónica Nacional de la Radiotelevisión Española y Coro Juvenil de Madrid']]]
  }
]

const PLAYLIST = {
  name: 'Perreo, Trap y Lo Que Venga — Mix Semanal Actualizado Cada Viernes a Medianoche',
  description:
    'Lo más escuchado de la semana en tu servidor: trap argentino, reggaetón y las sesiones de Bizarrap, mezclado con lo que más reprodujiste. Se actualiza cada viernes.'
}

/**
 * Returns a NEW base catalog (same shape as getCatalog()) with the realistic entries added
 * in front of the demo ones, so they surface first on Home, Library and in search.
 * @param {ReturnType<import('./catalog.mjs').getCatalog>} base
 */
export function withRealisticCatalog(base) {
  const artists = ARTISTS.map((name) => {
    const rng = rngFor(`artist:${name}`)
    return {
      id: `ar-${slugify(name)}`.slice(0, 60),
      name,
      bio: `${name} appears in the Nocturne mock server's realistic catalog, used to test long titles and multi-artist credits. Audio is synthesized.`,
      followers: randInt(rng, 120_000, 48_000_000),
      albumIds: [],
      trackIds: []
    }
  })
  const artistByName = new Map(artists.map((a) => [a.name, a]))
  const albums = []
  const tracks = []

  ALBUMS.forEach((d, albumIndex) => {
    const artist = artistByName.get(d.artist)
    const album = { id: `al-${slugify(d.title)}`.slice(0, 60), title: d.title, artistId: artist.id, year: d.year, type: d.type, trackIds: [] }
    const rng = rngFor(`album:${album.id}`)
    d.tracks.forEach(([title, names], i) => {
      const n = i + 1
      const id = `tr-${album.id.slice(3, 40)}-${String(n).padStart(2, '0')}`
      const artistIds = names.map((nm) => artistByName.get(nm).id)
      const track = {
        id,
        title,
        artistIds,
        albumId: album.id,
        duration: randInt(rng, 90, 150),
        trackNumber: n,
        explicit: rng() < 0.5,
        popularity: 0.6 + rng() * 0.4,
        lyricsMode: 'synced',
        music: { seed: `${id}:r${albumIndex}`, bpm: randInt(rng, 88, 118), mode: rng() < 0.5 ? 'minor' : 'major', root: randInt(rng, 0, 11), prog: randInt(rng, 0, 2) }
      }
      tracks.push(track)
      album.trackIds.push(id)
      for (const aid of artistIds) artists.find((a) => a.id === aid).trackIds.push(id)
    })
    artist.albumIds.push(album.id)
    albums.push(album)
  })

  const longIds = tracks.map((t) => t.id)
  const playlist = {
    id: `pl-${slugify(PLAYLIST.name)}`.slice(0, 60),
    name: PLAYLIST.name,
    description: PLAYLIST.description,
    trackIds: [...longIds, ...base.tracks.slice(0, 20 - longIds.length > 0 ? 20 - longIds.length : 0).map((t) => t.id)]
  }

  const allArtists = [...artists, ...base.artists]
  const allAlbums = [...albums, ...base.albums]
  const allTracks = [...tracks, ...base.tracks]
  const allPlaylists = [playlist, ...base.playlists]
  const nameOf = new Map(allArtists.map((a) => [a.id, a.name]))
  const albumTitle = new Map(allAlbums.map((a) => [a.id, a.title]))
  for (const t of tracks) t.search = fold(`${t.title} ${t.artistIds.map((id) => nameOf.get(id)).join(' ')} ${albumTitle.get(t.albumId)}`)
  for (const a of artists) a.search = fold(a.name)
  for (const a of albums) a.search = fold(`${a.title} ${nameOf.get(a.artistId)}`)
  playlist.search = fold(`${playlist.name} ${playlist.description}`)

  const defaults = {
    likedTrackIds: [...longIds.slice(0, 10), ...base.defaults.likedTrackIds],
    libraryAlbumIds: [...albums.map((a) => a.id), ...base.defaults.libraryAlbumIds],
    libraryArtistIds: [...artists.slice(0, 6).map((a) => a.id), artists[artists.length - 1].id, ...base.defaults.libraryArtistIds],
    libraryPlaylistIds: [playlist.id, ...base.defaults.libraryPlaylistIds],
    recentTrackIds: [...longIds.slice(0, 8), ...base.defaults.recentTrackIds].slice(0, 12)
  }

  return {
    artists: allArtists,
    albums: allAlbums,
    tracks: allTracks,
    playlists: allPlaylists,
    defaults,
    artistById: new Map(allArtists.map((a) => [a.id, a])),
    albumById: new Map(allAlbums.map((a) => [a.id, a])),
    trackById: new Map(allTracks.map((t) => [t.id, t])),
    playlistById: new Map(allPlaylists.map((p) => [p.id, p]))
  }
}
